<?php declare(strict_types=1); $heroActions = []; require dirname(__DIR__) . '/page-hero.php'; $values = (array) ($state['values'] ?? []); $errors = (array) ($state['errors'] ?? []); ?>
<section class="section contact-page"><div class="shell contact-grid"><aside><span class="section-label"><?= $e($t('contact.aside.label')) ?></span><h2><?= $e($t('contact.aside.title')) ?></h2><p><?= $e($t('contact.aside.copy')) ?></p><div class="contact-details"><a href="mailto:info@eduvixo.com"><?= $icon('messages') ?><span><small><?= $e($t('contact.aside.email')) ?></small><strong>info@eduvixo.com</strong></span></a><div><?= $icon('globe') ?><span><small><?= $e($t('contact.aside.scope')) ?></small><strong><?= $e($t('contact.aside.scope_value')) ?></strong></span></div><div><?= $icon('server') ?><span><small><?= $e($t('contact.aside.delivery')) ?></small><strong><?= $e($t('contact.aside.delivery_value')) ?></strong></span></div></div></aside><div class="contact-form-wrap"><?php if (!empty($state['success'])): ?><div class="form-success" role="status"><?= $icon('check') ?><div><h2><?= $e($t('contact.success.title')) ?></h2><p><?= $e($t('contact.success.copy')) ?></p></div></div><?php else: ?><form method="post" action="<?= $e($route('contact')) ?>" class="contact-form"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="started_at" value="<?= time() ?>"><label class="hp" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><?php if (isset($errors['form'])): ?><div class="form-error" role="alert"><?= $e($errors['form']) ?></div><?php endif; ?><div class="form-row"><label><span><?= $e($t('contact.fields.name')) ?></span><input name="name" maxlength="120" autocomplete="name" value="<?= $e($values['name'] ?? '') ?>" required><?php if (isset($errors['name'])): ?><small><?= $e($errors['name']) ?></small><?php endif; ?></label><label><span><?= $e($t('contact.fields.email')) ?></span><input type="email" name="email" maxlength="190" autocomplete="email" value="<?= $e($values['email'] ?? '') ?>" required><?php if (isset($errors['email'])): ?><small><?= $e($errors['email']) ?></small><?php endif; ?></label></div><div class="form-row"><label><span><?= $e($t('contact.fields.organization')) ?></span><input name="organization" maxlength="180" autocomplete="organization" value="<?= $e($values['organization'] ?? '') ?>" required><?php if (isset($errors['organization'])): ?><small><?= $e($errors['organization']) ?></small><?php endif; ?></label><label><span><?= $e($t('contact.fields.role')) ?></span><input name="role" maxlength="120" autocomplete="organization-title" value="<?= $e($values['role'] ?? '') ?>"></label></div><label><span><?= $e($t('contact.fields.topic')) ?></span><select name="topic" required><option value=""><?= $e($t('contact.fields.choose')) ?></option><?php foreach ((array) $t('contact.topics', []) as $key => $label): ?><option value="<?= $e($key) ?>"<?= ($values['topic'] ?? '') === $key ? ' selected' : '' ?>><?= $e($label) ?></option><?php endforeach; ?></select><?php if (isset($errors['topic'])): ?><small><?= $e($errors['topic']) ?></small><?php endif; ?></label><label><span><?= $e($t('contact.fields.message')) ?></span><textarea name="message" rows="7" maxlength="5000" required><?= $e($values['message'] ?? '') ?></textarea><?php if (isset($errors['message'])): ?><small><?= $e($errors['message']) ?></small><?php endif; ?></label><label class="consent"><input type="checkbox" name="privacy" value="1" required><span><?= $e($t('contact.fields.privacy')) ?> <a href="<?= $e($route('privacy')) ?>" target="_blank"><?= $e($t('nav.privacy')) ?></a>.</span></label><?php if (isset($errors['privacy'])): ?><small class="field-error"><?= $e($errors['privacy']) ?></small><?php endif; ?><button class="button button-primary" type="submit"><?= $e($t('contact.fields.submit')) ?><?= $icon('arrow-right') ?></button><p class="form-note"><?= $icon('shield-check') ?><?= $e($t('contact.fields.note')) ?></p></form><?php endif; ?></div></div></section>
